import ws from 'k6/ws'; import {check} from 'k6'; import {Rate} from 'k6/metrics'; import {baseURL,scenarioOptions} from '../lib/config.js'; import {routeSuccess} from '../lib/metrics.js';
const recovery=new Rate('ws_recovery_success');export const options=scenarioOptions('websocket',['route_success']);options.thresholds.ws_recovery_success=['rate==1'];export default function(){let echo=false,closed=false,opened=false;const r=ws.connect(`${baseURL().replace(/^http/,'ws')}/ws`,{tags:{route_family:'ws',operation:'echo',expected_status:'101'}},s=>{s.setTimeout(()=>s.close(),3000);s.on('open',()=>{opened=true;s.send('ping')});s.on('message',m=>{echo=check(m,{'ws echo payload matches ping':x=>x==='ping','ws echo payload nonempty':x=>x.length>0});s.close()});s.on('close',()=>{closed=true})});const ok=check(r,{'ws upgrade status 101':x=>x.status===101,'ws upgrade accept header present':x=>Boolean(x.headers['Sec-WebSocket-Accept']||x.headers['sec-websocket-accept']),'ws handshake duration bounded':x=>x.timings.duration<3000,'ws response object present':x=>Boolean(x)})&&check(opened,{'ws open event observed':x=>x===true})&&echo&&check(closed,{'ws close event observed':x=>x===true});routeSuccess.add(ok,{route_family:'ws',operation:'echo'});recovery.add(ok,{route_family:'ws'});}
